// A Level H2 Computing (9569, revised syllabus from 2027) — Module 1 Programming Fundamentals
// Lives at: src/features/flashcards/data/decks/a-h2-computing-1.js
//
// Scope follows the official SEAB 9569 syllabus learning outcomes 1.1–1.5. Code uses Python 3 and
// only functions listed in the syllabus Reference Guide. Every question is ORIGINAL.
// Code-tracing questions are generated by code: the expected output is computed by a small model of
// Python's rules (floor division, modulo, slicing, list/dict methods, exceptions), so it always matches.
// Definitions in quotation marks are verbatim from the free OpenStax "Introduction to Python Programming".
//
// Extra card field used here: code — a Python snippet shown in a code box on the front of the card.

import { deck, pick } from './helpers.js';

const SYLLABUS = outcome => `SEAB H2 Computing 9569 syllabus (2027), ${outcome}`;
const PYBOOK = chapter => `OpenStax Introduction to Python Programming, ch. ${chapter}`;

// Builds a NUMBER card: the original card and every variation come from the same build() function.
function numberCard(id, difficulty, ref, build, defaults, makeValues, seconds) {
  return {
    id, difficulty, ref, ...(seconds ? { seconds } : {}),
    ...build(defaults),
    vary: { make: rand => build(makeValues(rand)) },
  };
}

// ---------- A tiny model of Python behaviour ----------

const pyFloorDiv = (a, b) => Math.floor(a / b);
const pyMod = (a, b) => ((a % b) + b) % b;

// How Python prints a value inside a list/dict (repr) or on its own (str).
function pyRepr(value) {
  if (typeof value === 'string') return `'${value}'`;
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return String(value); // only whole numbers appear in these lists and dicts
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) return `{${[...value].map(([k, v]) => `${pyRepr(k)}: ${pyRepr(v)}`).join(', ')}}`;
  return String(value);
}

// Python's str() of a float always shows a decimal point: 4 → "4.0", 3.5 → "3.5"
function pyFloat(x) {
  return Number.isInteger(x) ? `${x}.0` : String(x);
}

// Python slice s[start:stop:step] for a positive step.
function pySlice(s, start, stop, step = 1) {
  const n = s.length;
  const fix = (i, dflt) => (i === undefined ? dflt : i < 0 ? Math.max(0, n + i) : Math.min(i, n));
  const a = fix(start, 0);
  const b = fix(stop, n);
  let out = '';
  for (let i = a; i < b; i += step) out += s[i];
  return out;
}

const WORDS = ['COMPUTING', 'ALGORITHM', 'RECURSION', 'VARIABLE', 'FUNCTION', 'DICTIONARY', 'BOOLEAN', 'ITERATION', 'PYTHON', 'DATABASE'];
const KEYWORDS = ['def', 'class', 'return', 'if', 'else', 'for', 'while', 'in', 'not', 'and', 'or', 'True', 'False', 'None', 'import', 'global', 'try', 'except', 'lambda', 'pass'];

