    alternates: [
      { question: 'A website asks you to type your new email address twice. Is this validation or verification?', answer: 'Verification — it checks the data was entered accurately by comparing the two entries.' },
      { question: 'Can a valid date of birth still be wrong? Explain.', answer: 'Yes. Validation only checks that the data is reasonable (e.g. a real date in range); a mistyped but possible date passes validation.' },
      { question: 'A program rejects an age of 250. Is this validation or verification?', answer: 'Validation (a range check).' },
    ],
