        question: 'What is printed for each input s?',
        code: `def share(s):\n    try:\n        n = int(s)\n        print(${total} // n)\n    except ValueError:\n        print("Not a whole number")\n    except ZeroDivisionError:\n        print("Cannot divide by zero")\n\n${inputs.map(s => `share("${s}")`).join('\n')}`,
